<script lang="ts">import { enhance } from '$app/forms';import {thumbUrl} from '$lib/client/api';let {data,form}=$props();</script>
<a class="button-quiet" href={`/admin/events/${data.event.id}/access`}>← Sharing & proofing</a><h1 class="mt-5 text-3xl font-semibold">{data.round.title}</h1><p class="mt-3">{data.round.status} · revision {data.round.version} · {data.round.selected.length} selected</p>
{#if form?.error}<p role="alert" class="notice mt-4">{form.error}</p>{/if}{#if form?.ok}<p role="status" class="notice mt-4">{form.ok}</p>{/if}
<p class="my-4 whitespace-pre-line">{data.round.message}</p><div class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each data.round.selected as id}{@const photo=data.photos.find(p=>p.id===id)}<article class="rounded-xl border p-3">{#if photo}<img src={thumbUrl(id,photo.hash)} alt={`Photo ${id}`} class="h-48 w-full object-contain" /><p>{photo.label} · Photo {id}</p>{:else}<p>Photo {id} · no longer available</p>{/if}<p class="whitespace-pre-line">{data.round.photoNotes[String(id)]??''}</p></article>{/each}</div>
<form method="post" use:enhance class="mt-6 rounded-xl border p-5"><input type="hidden" name="version" value={data.round.version} /><label class="block">Feedback for recipient<textarea name="reviewNote" maxlength="2000" class="mt-2 block w-full rounded-lg border p-3">{data.round.review_note}</textarea></label><div class="mt-4 flex flex-wrap gap-3">{#if data.round.status==='submitted'}<button class="button-primary" name="status" value="accepted">Accept selection</button>{/if}<button class="button-secondary" name="status" value="open">Reopen for changes</button><button class="button-secondary" name="status" value="closed">Close round</button></div></form>
<details class="mt-6"><summary class="font-semibold">Submission history ({data.history.length})</summary>{#each data.history as h}<article class="my-3 rounded-xl border p-4"><h2>Revision {h.revision} · {h.submitted_at}</h2><p>Photos: {h.selected.join(', ')}</p><p class="whitespace-pre-line">{h.message}</p>{#each Object.entries(h.photoNotes) as [id,note]}<p class="whitespace-pre-line">Photo {id}: {note}</p>{/each}</article>{/each}</details>
